config:
events {}

http {

    include /etc/nginx/mime.types;

    default_type application/octet-stream;

    sendfile on;

    map $http_upgrade $connection_upgrade {

        default upgrade;

        "" close;

    }

    server {
        listen 80 default_server;
        listen [::]:80 default_server;
        server_name _;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass http://127.0.0.1:3000/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        location ^~ / {
            return 404;
        }
    }

    server {
        listen 80;
        listen [::]:80;
        server_name api.home.arpa;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass http://127.0.0.1:3000/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        return 308 https://$host$request_uri;
    }

    server {
        listen 443 ssl http2;
        listen [::]:443 ssl http2;
        server_name api.home.arpa;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass http://127.0.0.1:3000/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        ssl_certificate /var/lib/proxycore/candidates/rev-1/nginx/certs/cert-api.crt;
        ssl_certificate_key /var/lib/proxycore/candidates/rev-1/nginx/certs/cert-api.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_http_version 1.1;
        proxy_connect_timeout 5s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
        client_header_timeout 15s;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
        proxy_buffering off;
        proxy_set_header x-homelab proxycore;
        client_max_body_size 100m;
        add_header X-Robots-Tag "noindex" always;
        location = /health {
            return 307 /ready;
        }
        location / {
            proxy_pass http://10.0.0.20:8080;
            proxy_buffering off;
        }
    }

}

stream {
    server {
        listen 0.0.0.0:5432;
        proxy_pass 10.0.0.30:5432;
    }
}

